/* Roda Codigo.gs contra uma planilha de mentira, para conferir a lógica da fila. */
const fs = require('fs');
const vm = require('vm');

function novaAba(nome) {
  const dados = [];                                // matriz de linhas
  const garantir = (linhas, cols) => {
    while (dados.length < linhas) dados.push([]);
    dados.forEach(l => { while (l.length < cols) l.push(''); });
  };
  return {
    nome,
    dados,
    getLastRow(){
      for (let i = dados.length - 1; i >= 0; i--) {
        if (dados[i].some(v => v !== '' && v != null)) return i + 1;
      }
      return 0;
    },
    setFrozenRows(){},
    appendRow(linha){ dados[this.getLastRow()] = linha.slice(); },
    deleteRow(n){ dados.splice(n - 1, 1); },
    getRange(l, c, nl, nc){
      nl = nl || 1; nc = nc || 1;
      garantir(l + nl - 1, c + nc - 1);
      return {
        getValues(){
          const saida = [];
          for (let i = 0; i < nl; i++) saida.push(dados[l - 1 + i].slice(c - 1, c - 1 + nc));
          return saida;
        },
        setValues(v){
          for (let i = 0; i < nl; i++)
            for (let j = 0; j < nc; j++) dados[l - 1 + i][c - 1 + j] = v[i][j];
          return this;
        },
        clearContent(){
          for (let i = 0; i < nl; i++)
            for (let j = 0; j < nc; j++) dados[l - 1 + i][c - 1 + j] = '';
          return this;
        },
        setFontWeight(){ return this; },
        setBackground(){ return this; },
        setFontColor(){ return this; }
      };
    }
  };
}

